class Solution {
    public int regionsBySlashes(String[] grid) {
        int n = grid.length;
        int total = n * n * 4;
        DSU dsu = new DSU(total);
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                char c = grid[i].charAt(j);
                int base = (i * n + j) * 4;
                // internal unions
                if (c == ' ') {
                    dsu.union(base + 0, base + 1);
                    dsu.union(base + 1, base + 2);
                    dsu.union(base + 2, base + 3);
                } else if (c == '/') {
                    dsu.union(base + 0, base + 3);
                    dsu.union(base + 1, base + 2);
                } else if (c == '\\') {
                    dsu.union(base + 0, base + 1);
                    dsu.union(base + 2, base + 3);
                }
                // union with cell below
                if (i + 1 < n) {
                    int baseBelow = ((i + 1) * n + j) * 4;
                    dsu.union(base + 2, baseBelow + 0);
                }
                // union with cell to the right
                if (j + 1 < n) {
                    int baseRight = (i * n + (j + 1)) * 4;
                    dsu.union(base + 1, baseRight + 3);
                }
            }
        }
        // count distinct roots
        int regions = 0;
        for (int k = 0; k < total; ++k) {
            if (dsu.find(k) == k) regions++;
        }
        return regions;
    }

    private static class DSU {
        int[] parent;
        int[] rank;
        DSU(int n) {
            parent = new int[n];
            rank = new int[n];
            for (int i = 0; i < n; ++i) parent[i] = i;
        }
        int find(int x) {
            if (parent[x] != x) parent[x] = find(parent[x]);
            return parent[x];
        }
        void union(int a, int b) {
            int ra = find(a), rb = find(b);
            if (ra == rb) return;
            if (rank[ra] < rank[rb]) parent[ra] = rb;
            else if (rank[rb] < rank[ra]) parent[rb] = ra;
            else {
                parent[rb] = ra;
                rank[ra]++;
            }
        }
    }
}

